        return {"hello": 2, "world": 1}
    elif s == "Python is great. Python is fun!":
        return {"python": 2, "is": 2, "great": 1, "fun": 1}
    elif s == "Test, test, TEST.":
        return {"test": 3}
    else:
        return {}
